#!/usr/bin/python
"""Mock completion/list-change races. No storage operations are invoked."""
import ast
from pathlib import Path
import os
import shutil
import subprocess
import tempfile

source=Path(__file__).parent
nodes=ast.parse((source/'qml_smoke.py').read_text()).body
shell=ast.literal_eval(nodes[0].value)
helper=ast.literal_eval(nodes[1].value)
checks='            var notices = []\n            widget.notificationRequested.connect(function(message) { if (message.indexOf(": safe to unplug.") >= 0 && widget.opened) throw new Error("Success notice obscured by popup"); notices.push(message) })\n            var a = {path:"/a",token:"old-a",device:"/dev/sdb",name:"USB",error:"",displayName:"[sdb] USB",volumes:[{name:"DATA"}]}\n            var b = {path:"/b",token:"b",device:"/dev/sdc",name:"USB",error:"",displayName:"[sdc] USB",volumes:[{name:"DATA"}]}\n            function begin(id, drive) {\n                widget.discoveryEpoch++\n                widget.operation = {id:id,path:drive.path,token:drive.token,device:drive.device,label:widget.operationLabel(drive),verb:"eject",complete:false,successReceived:false,discoverySeen:false,deadline:0}\n                widget.activeVerb = "eject"\n            }\n            function scan(list) { widget.acceptDiscovery({drives:list},widget.discoveryEpoch) }\n            widget.drives = [a,b]\n            widget.open()\n            begin("a1",a)\n            var staleEpoch = widget.discoveryEpoch - 1\n            widget.handleResult({requestId:"a1",success:true})\n            var popup = null\n            for (var n = 0; n < widget.data.length; n++) if (widget.data[n].objectName === "usbPopup") popup = widget.data[n]\n            var menu = popup.contentItem[0].contentChildren[0]\n            function pendingRows(item) {\n                var count = item.objectName === "usbEjectAction" && item.text === "Ejecting…" && !item.enabled ? 1 : 0\n                if (item.children) for (var j = 0; j < item.children.length; j++) count += pendingRows(item.children[j])\n                return count\n            }\n            if (pendingRows(menu) !== 1) throw new Error("Specific target row lacks Ejecting feedback")\n            if (!widget.busy || notices.length || widget.operation.complete) throw new Error("Success notified before discovery")\n            if (widget.status.indexOf("confirming removal") < 0) throw new Error("No pending feedback")\n            widget.run("eject",b,null)\n            if (widget.operation.id !== "a1") throw new Error("Repeated click escaped guard")\n            widget.acceptDiscovery({drives:[]},staleEpoch)\n            if (widget.drives.length !== 2 || notices.length) throw new Error("Old scan accepted")\n            scan([a,b])\n            if (!widget.busy || notices.length) throw new Error("Still-present drive confirmed safe")\n            scan([b])\n            if (widget.status !== "" || widget.opened || widget.busy || notices.length !== 1 || notices[0] !== "[sdb] USB — DATA: safe to unplug.") throw new Error("Delayed reconciliation failed")\n            if (widget.drives[0].token !== "b") throw new Error("Remaining drive changed")\n            widget.handleResult({requestId:"a1",success:true})\n            if (notices.length !== 1) throw new Error("Duplicate reply notified")\n            // Scan before the helper response: no confirmation until both arrive.\n            widget.drives = [a]\n            widget.open()\n            begin("a2",a)\n            scan([])\n            if (widget.opened || notices.length !== 1 || !widget.busy) throw new Error("Disappearance counted as success")\n            widget.handleResult({requestId:"a1",success:true})\n            if (notices.length !== 1) throw new Error("Stale operation reply accepted")\n            a.displayName = "Changed after action"\n            widget.handleResult({requestId:"a2",success:true})\n            if (notices.length !== 2 || notices[1].indexOf("[sdb]") !== 0 || widget.busy) throw new Error("Fresh disappearance and matching success failed")\n            a.displayName = "[sdb] USB"\n            widget.drives = [a,b]\n            widget.open()\n            begin("b1",b)\n            scan([a,b])\n            widget.handleResult({requestId:"b1",error:"This drive is still in use."})\n            if (!widget.statusError || widget.status.indexOf("[sdc]") < 0 || !widget.opened || widget.busy || notices.length !== 2) throw new Error("Busy error lifecycle failed")\n            // Missing drive plus a failed operation never confirms safe removal.\n            begin("a3",a)\n            scan([b])\n            widget.handleResult({requestId:"a3",error:"Removal failed"})\n            if (widget.status !== "" || notices[2].indexOf("safe to unplug") >= 0) throw new Error("Missing device falsely safe")\n            widget.drives = [a]\n            begin("a4",a)\n            widget.handleResult({requestId:"a4",success:true})\n            scan([{path:"/a",token:"replacement",device:"/dev/sdb",name:"USB",error:"",volumes:[]}])\n            if (notices[3].indexOf("safe to unplug") >= 0 || widget.busy) throw new Error("Replacement falsely safe")\n            // Success without a confirming list is bounded, and late data cannot revive it.\n            widget.drives = [a,b]\n            begin("a5",a)\n            widget.handleResult({requestId:"a5",success:true})\n            scan([a,b])\n            widget.checkReconciliationDeadline(widget.operation.deadline + 1)\n            if (widget.busy || !widget.statusError || notices.length !== 4) throw new Error("Reconciliation timeout unsafe")\n            scan([b])\n            widget.handleResult({requestId:"a5",success:true})\n            if (notices.length !== 4) throw new Error("Late result revived timed-out success")\n            // A repeated fresh flow still works after errors/timeouts.\n            widget.drives = [a]\n            widget.open()\n            begin("a6",a)\n            widget.handleResult({requestId:"a6",success:true})\n            scan([])\n            if (widget.status !== "" || widget.opened || widget.busy || notices.length !== 5) throw new Error("Final-drive repeated flow failed")\n            widget.drives = [b]\n            widget.close()\n            begin("b2",b)\n            widget.handleResult({requestId:"b2",error:"This drive is still in use."})\n            if (notices.length !== 6 || notices[5].indexOf("[sdc]") < 0 || !widget.statusError) throw new Error("Hidden error fallback missing")\n            widget.open()\n            if (widget.status.indexOf("still in use") < 0 || notices.length !== 6) throw new Error("Reopen lost error or duplicated it")\n            widget.handleResult({requestId:"b2",error:"This drive is still in use."})\n            if (notices.length !== 6) throw new Error("Duplicate error notification")\n            widget.close()\n            console.info("USB_FEEDBACK_VISIBILITY_PASS")\n            console.info("USB_TARGETED_COMPLETION_PASS")\n            console.info("USB_RECONCILIATION_ORDERING_PASS")\n            Qt.quit()\n'

shell=shell.replace('            Qt.quit()',checks)
with tempfile.TemporaryDirectory(prefix='usb-target-') as tmp:
    root=Path(tmp)
    for name in ('Ui','Commons'):
        (root/name).symlink_to('/usr/share/omarchy/shell/'+name,target_is_directory=True)
    for name in ('Widget.qml','UsbMenu.qml'):
        shutil.copy2(source/name,root/name)
    (root/'shell.qml').write_text(shell)
    (root/'usb_helper.py').write_text(helper)
    (root/'notify-send').write_text('#!/bin/sh\nexit 0\n');(root/'notify-send').chmod(0o700)
    runtime=root/'runtime';runtime.mkdir(mode=0o700)
    env=dict(os.environ,PATH=str(root)+os.pathsep+os.environ['PATH'],XDG_RUNTIME_DIR=str(runtime),QT_QPA_PLATFORM='offscreen',QT_QPA_PLATFORMTHEME='generic',QT_QUICK_CONTROLS_STYLE='Basic')
    result=subprocess.run(['quickshell','-p',str(root/'shell.qml'),'--no-color'],env=env,capture_output=True,text=True,timeout=8)
    output=result.stdout+result.stderr
    print(output)
    assert result.returncode == 0 and 'USB_TARGETED_COMPLETION_PASS' in output
    assert 'WARN scene:' not in output
